    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            if current_group:
                groups.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append("(")
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    # Step 4: Combine the balanced groups into distinct strings
    result = []
    current_valid_group = ""
    for group in groups:
        if is_balanced(group):
            current_valid_group += group
        else:
            if current_valid_group:
                result.append(current_valid_group)
            current_valid_group = ""

    if current_valid_group:
        result.append(current_valid_group)

    return result

